create or replace function public.mark_messages_read(p_conversation_id uuid,p_user_id uuid) returns void language plpgsql security definer set search_path='' as $$ begin if auth.uid() is null or p_user_id is distinct from auth.uid() or not public.hayna_is_conversation_member(p_conversation_id,auth.uid()) then raise exception 'Conversation access denied' using errcode='42501'; end if; update public.messages set read_by=array_append(coalesce(read_by,'{}'::uuid[]),p_user_id) where conversation_id=p_conversation_id and sender_id<>p_user_id and not(coalesce(read_by,'{}'::uuid[]) @> array[p_user_id]); end $$; revoke all on function public.mark_messages_read(uuid,uuid) from public,anon; grant execute on function public.mark_messages_read(uuid,uuid) to authenticated;
